package serve

import (
	"embed"
	"io/fs"
)

// assets is the embedded UI: the shell page, the stylesheet, and the bundle built
// from web/ TypeScript. Nothing is fetched at run time, so the app stays usable
// with no network (AC11), and the files are part of the binary.
//
// web/ is the source; static/app.js is its build output, regenerated by
// web/build.sh (and rebuilt inside the nix derivation). A test fails when the two
// have drifted.
//
//go:embed static
var embedded embed.FS

// static is the embedded directory rooted so paths read as "index.html", "app.js".
var static = mustSub(embedded, "static")

func mustSub(fsys fs.FS, dir string) fs.FS {
	sub, err := fs.Sub(fsys, dir)
	if err != nil {
		panic("serve: embedded assets: " + err.Error())
	}
	return sub
}
